package Testing_First;

public class First_String {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		final String name = "John ";
		System.out.println(name.length()); //length of string
		System.out.println(name.charAt(0)); // character placement
		System.out.println(name.trim()); // trim space for front and back
		System.out.println(name.replace("J","K")); // replace character
		
		
	}
}
